class Solution {
public:
    int divisorSubstrings(int num, int k) {
        std::string s = std::to_string(num);
        int count = 0;
        for (int i = 0; i + k <= (int)s.size(); ++i) {
            int val = std::stoi(s.substr(i, k));
            if (val != 0 && num % val == 0) {
                ++count;
            }
        }
        return count;
    }
};

class Solution {
    public int divisorSubstrings(int num, int k) {
        String s = String.valueOf(num);
        int count = 0;
        for (int i = 0; i + k <= s.length(); i++) {
            int val = Integer.parseInt(s.substring(i, i + k));
            if (val != 0 && num % val == 0) {
                count++;
            }
        }
        return count;
    }
}

var divisorSubstrings = function(num, k) {
    const s = String(num);
    let count = 0;
    for (let i = 0; i + k <= s.length; i++) {
        const val = parseInt(s.substring(i, i + k), 10);
        if (val !== 0 && num % val === 0) {
            count++;
        }
    }
    return count;
};
